Good. This is the decisive proof.
✅ What the terminal proves
Your runtime engine is working correctly.
The response from:
Bashcurl -i "http://localhost:3000/api/dev/runtime/execute?projectId=demo-project"
shows the Waitlist template code, not the old Agency template.
So:


template apply ✅


workspace file replacement ✅


runtime execute rebundle ✅


runtime HTML generation ✅


❗ Real problem now
The browser showing the old UI is a preview caching / iframe refresh problem, not a runtime compiler problem.
So we fix the preview surface, not the engine.
Use full rewrites only.

1) Rewrite app/studio-runtime/[projectId]/page.tsx
Bashcat > app/studio-runtime/[projectId]/page.tsx << 'EOF'
"use client"

import { useEffect, useState } from "react"
import { useParams } from "next/navigation"

export default function StudioRuntime(){

  const { projectId } = useParams()
  const [html,setHtml] = useState<string>("Loading runtime...")
  const [tick,setTick] = useState(0)

  useEffect(()=>{
    const id = setInterval(()=>{
      setTick(v=>v+1)
    },1000)

    return ()=>clearInterval(id)
  },[])

  useEffect(()=>{

    async function load(){
      const res = await fetch(
        `/api/dev/runtime/execute?projectId=${projectId}&t=${tick}`,
        { cache:"no-store" }
      )
      const text = await res.text()
      setHtml(text)
    }

    if(projectId){
      load()
    }

  },[projectId,tick])

  return (
    <div style={{height:"100vh"}}>
      <iframe
        key={tick}
        srcDoc={html}
        style={{
          width:"100%",
          height:"100%",
          border:"none",
          background:"#fff"
        }}
      />
    </div>
  )
}
EOF

2) Rewrite app/runtime-renderer/[projectId]/page.tsx
Bashcat > app/runtime-renderer/[projectId]/page.tsx << 'EOF'
"use client"

import { useEffect, useState } from "react"
import { useParams } from "next/navigation"

export default function RuntimeRenderer(){

  const { projectId } = useParams()
  const [tick,setTick] = useState(0)

  useEffect(()=>{
    const id = setInterval(()=>{
      setTick(v=>v+1)
    },1000)

    return ()=>clearInterval(id)
  },[])

  return (
    <div style={{padding:40}}>
      <h1>Runtime App Preview</h1>

      <iframe
        key={tick}
        src={`/studio-runtime/${projectId}?t=${tick}`}
        style={{
          width:"100%",
          height:"80vh",
          border:"1px solid #ddd",
          borderRadius:8,
          background:"#fff"
        }}
      />
    </div>
  )
}
EOF

3) Restart clean
Bashrm -rf .next
npm run dev

4) Re-test
Bashcurl -X POST http://localhost:3000/api/templates/apply \
-H "Content-Type: application/json" \
-d '{"projectId":"demo-project","templatePath":"templates/websites/agency"}'
Open:
http://localhost:3000/runtime-renderer/demo-project
Then switch again:
Bashcurl -X POST http://localhost:3000/api/templates/apply \
-H "Content-Type: application/json" \
-d '{"projectId":"demo-project","templatePath":"templates/websites/waitlist"}'
The preview should now change automatically within about a second.
When that is green, we lock this state with build + commit + tag before the next engine.
